16|// ============================================================================
17|// Token Estimation and Formatting Helpers
18|// ============================================================================
19|
20|export interface TokenStats {
21|  beforeChars: number;
22|  afterChars: number;
23|  savedChars: number;
24|  reductionRatio: number;
25|}
26|
27|export function formatBytes(bytes: number, decimals: number = 2): string {
28|  if (bytes === 0) return '0 Bytes';
29|  const k = 1024;
30|  const dm = decimals < 0 ? 0 : decimals;
31|  const sizes = ['Bytes', 'KB', 'MB', 'GB'];
32|  const i = Math.floor(Math.log(bytes) / Math.log(k));
33|  return parseFloat((bytes / Math.pow(k, i)).toFixed(dm)) + ' ' + sizes[i];
34|}
35|
36|export function calculateStats(before: number, after: number): TokenStats {
37|  const saved = Math.max(0, before - after);
38|  const ratio = before > 0 ? (saved / before) : 0;
39|  return {
40|    beforeChars: before,
41|    afterChars: after,
42|    savedChars: saved,
43|    reductionRatio: Math.round(ratio * 1000) / 1000,
44|  };
45|}
46|
47|export function truncateIdentifier(id: string, maxLen: number = 16): string {
48|  if (id.length <= maxLen) return id;
49|  return id.substring(0, maxLen - 3) + '...';
50|}
